 q('md-checklist').innerHTML=eligible.map(r=>{const d=decide(r.codigo),url=safeLink(r.fonte_url),preview=evidencePreview(r,ev);return `<tr data-matrix-code="${h(r.codigo)}"><td class="md-check"><input aria-label="Incluir ${h(r.codigo)} na minuta" type="checkbox" data-md-include="${h(r.codigo)}" ${d.include?'checked':''}></td><td><strong>${h(r.codigo)}</strong><div class="muted">${h(r.etapa)}</div></td><td><strong>${h(r.documento)}</strong><p class="muted">${h(r.classificacao)}</p><p class="md-evidence">${h(preview)}</p></td><td>${h(r.aplicabilidade)}<p class="muted">${h(r.prazo||'')}</p></td><td>${url?`<a href="${h(url)}" target="_blank" rel="noopener noreferrer">Fonte oficial</a>`:'Fonte não verificada'}<p class="muted">${h(r.fundamento)}</p></td><td><select aria-label="Conferência de ${h(r.codigo)}" data-md-status="${h(r.codigo)}"><option value="a_conferir" ${d.status==='a_conferir'?'selected':''}>A conferir</option><option value="solicitar" ${d.status==='solicitar'?'selected':''}>Solicitar comprovação</option><option value="localizado" ${d.status==='localizado'?'selected':''}>Localizado; conferir</option><option value="conferido" ${d.status==='conferido'?'selected':''}>Conferido</option><option value="nao_aplicavel" ${d.status==='nao_aplicavel'?'selected':''}>Não aplicável</option></select><textarea data-md-notes="${h(r.codigo)}" rows="2" maxlength="1500" placeholder="Referência SEI, páginas ou ressalva...">${h(d.notes)}</textarea></td></tr>`}).join('')||'<tr><td colspan="6" class="empty">Confirme uma etapa para apresentar a matriz documental correspondente.</td></tr>';
