function refresh(reevaluate=false){
 const p=project();draftText='';q('md-subject').value='';q('md-body').value='';q('md-feedback').textContent='';
 if(!p){q('md-context').textContent='Selecione o empreendimento; a etapa será sugerida conforme as evidências disponíveis.';q('md-checklist').innerHTML='';q('md-matrix-count').textContent='Sem empreendimento selecionado';chosenStages.clear();q('md-confirm-stage').checked=false;chips();return;}
 if(reevaluate){chosenStages.clear();q('md-confirm-stage').checked=false;}
 summary(projectEvidence());table();
}
function changedProject(){const id=q('md-project').value;if(id!==currentId){currentId=id;refresh(true)}else refresh(false)}
function keyStatusLabel(s){return {a_conferir:'Localização e suficiência a confirmar',solicitar:'Comprovação/esclarecimento a solicitar',localizado:'Documento indicado, conteúdo pendente de conferência',conferido:'Documento conferido',nao_aplicavel:'Não aplicável (justificativa a verificar)'}[s]||'A conferir'}
function requestLanguage(r){switch(r.classificacao){
case 'REMESSA EXPRESSA À SNP/MPOR':return 'Solicita-se indicar a remessa à SNP/MPOR, o registro de protocolo e, se pertinente, complementar a documentação prevista na etapa.';
case 'CONTEÚDO OBRIGATÓRIO DO PLANO':return 'Solicita-se indicar o Plano de Investimentos e a seção/página que contempla o conteúdo exigido, sem presumir que seja anexo autônomo.';
case 'DEVER LEGAL DA ESTATAL':return 'Solicita-se informar a forma de disponibilização/consulta da informação, observadas as hipóteses legais de sigilo; não se presume obrigação de remessa automática à SNP.';
default:return 'Se aplicável, solicita-se indicar ou encaminhar a evidência complementar pertinente, ou justificar documentalmente a inaplicabilidade.';
}}
function makeDraft(){
 const p=project();if(!p){q('md-feedback').textContent='Selecione um empreendimento.';return}
 if(!chosenStages.size||!q('md-confirm-stage').checked){q('md-feedback').textContent='Selecione e confirme a(s) etapa(s) aplicável(is) antes de gerar a minuta.';return}
 const selected=RULES.filter(r=>chosenStages.has(r.etapa)&&decide(r.codigo).include&&['solicitar','a_conferir'].includes(decide(r.codigo).status));
 if(!selected.length){q('md-feedback').textContent='Marque ao menos um documento/evidência para análise na minuta. Itens já conferidos ou não aplicáveis não são solicitados.';return}
 const ev=projectEvidence(),diffs=ev.audits.filter(a=>a.status==='DIVERGÊNCIA NUMÉRICA');
 const chronology=(typeof scheduleFindings==='function'?scheduleFindings(ev.sch):[]).filter(f=>['DATAS DIFERENTES','TÉRMINO POSTERIOR AO PREVISTO','INCONSISTÊNCIA CRONOLÓGICA'].includes(f.status)).slice(0,6);
 const baseSummary=[];
 for(const row of ev.s.slice(0,12))baseSummary.push(`- SIOP 2026: ação ${row.acao||'a confirmar'} / PO ${row.po||'a confirmar'} · dotação atual ${fmtMoney(row.dotacao_atual)} · empenhado ${fmtMoney(row.empenhado)} · liquidado ${fmtMoney(row.liquidado)} · pago ${fmtMoney(row.pago)}. Valores da União, sem comprovação de recebimento/aplicação pela Docas.`);
 if(!baseSummary.length)baseSummary.push('- SIOP: nenhum registro atribuído com segurança ao empreendimento nesta sessão.');
 const verifiedBm=ev.bms.filter(x=>x.status==='confirmado').sort((a,b)=>String(a.date||'').localeCompare(String(b.date||'')));
 const lastByContract=new Map();for(const bm of verifiedBm)lastByContract.set(bm.contract||'Contrato a identificar',bm);
 for(const [contract,bm] of lastByContract)baseSummary.push(`- SEI/BM · contrato ${contract}: BM nº ${bm.number||'a confirmar'} · medição ${bm.date||'sem data'} · avanço físico acumulado ${bm.physical===null||bm.physical===undefined?'não informado':Number(bm.physical).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%'} · valor do BM ${fmtMoney(bm.measured)} · medição acumulada ${fmtMoney(bm.cumulative)} · documento ${bm.evidence||'referência a confirmar'}. Dados de medição não equivalem a pagamentos.`);
 if(!lastByContract.size)baseSummary.push('- SEI/BMs: nenhuma medição conferida e associada ao projeto nesta sessão; não se presume ausência no processo.');
 if(ev.bal){const b=ev.bal;baseSummary.push(`- Balanço externo: ${b.verified?'registro assinalado como conferido':'registro ainda não conferido'} · valor global ${fmtMoney(b.global)} · físico ${b.physical===null||b.physical===undefined?'não informado':Number(b.physical).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%'} · financeiro ${b.financial===null||b.financial===undefined?'não informado':Number(b.financial).toLocaleString('pt-BR',{maximumFractionDigits:2})+'%'} · início ${b.start||'a conferir'} · conclusão prevista ${b.end_plan||'a conferir'} · término efetivo ${b.end_real||'não informado'} · data de corte ${b.cutoff||'não informada'} · fonte ${b.evidence||'não registrada'}. Percentuais do empreendimento não são valores pagos pelo SIOP.`)}
 else baseSummary.push('- Balanço externo: não incluído nesta sessão; valor global, execução e cronograma devem ser consultados na fonte original.');
 const docas=ev.obs.filter(x=>x.source==='DOCAS'&&x.verified);baseSummary.push(`- Docas: ${docas.length} registro(s) com evidência conferida no confronto; dados não carregados não significam execução zero.`);

 const lines=[
 'Prezados(as),','',
 `No âmbito do acompanhamento dos aportes de Participação da União no Capital (PUC), e em análise preliminar do empreendimento “${p.empreendimento}” (${p.id}; ${p.empresa}; UF ${p.uf||'a confirmar'}; ação ${p.acao||'a confirmar'}/PO ${p.po||'a confirmar'}), solicitamos esclarecimentos sobre os registros e os documentos abaixo relacionados, observada a aplicabilidade de cada exigência.`,
 '',`ETAPA(S) EM ANÁLISE, CONFIRMADA(S) PELO ANALISTA: ${[...chosenStages].sort().join(' | ')}`,
 '',`FONTES CONSULTADAS NESTA SESSÃO: Consulta SIOP 2(1).xlsx (${ev.s.length} registro(s) associado(s), data de extração não comprovada); SEI/BMs (${ev.bms.length} BM(s) conferido(s) na ficha); Balanço (${ev.bal?'registro disponível, conferência '+(ev.bal.verified?'indicada':'pendente'):'não integrado'}); Docas (${ev.obs.filter(x=>x.source==='DOCAS').length} registro(s)). Informações não carregadas não permitem afirmar que o documento inexiste no processo.`,
 '','1. RESULTADO DO CONFRONTO DAS FONTES','',...baseSummary,'', '1.1 DIFERENÇAS COMPARÁVEIS / RESSALVAS'];
 if(!diffs.length&&!chronology.length)lines.push('Nos dados estritamente equivalentes e conferidos desta sessão, não foram registradas divergências numéricas ou cronológicas confirmadas. Não se trata de atestado de regularidade; persiste a necessidade de verificar as evidências indicadas.');
 for(const a of diffs.slice(0,6))lines.push(`- ${a.indicator}: ${sourceLabel(a.source_a)} (${fmtIndicator(a.value_a,a.unit)}) x ${sourceLabel(a.source_b)} (${fmtIndicator(a.value_b,a.unit)}). Situação: ${a.status}. Evidências: ${a.evidence_a||'não informada'}; ${a.evidence_b||'não informada'}. Período e objeto somente conforme validações do BI.`);
 for(const f of chronology)lines.push(`- ${f.status}: ${f.reason}. Referência: ${f.evidence||'pendente'}.`);
 lines.push('','2. RELAÇÃO DOCUMENTAL — MATRIZ_PUC_2026 / ABA MATRIZ DOCUMENTAL');
 selected.forEach((r,i)=>{const d=decide(r.codigo);lines.push('',`${i+1}. CÓDIGO: ${r.codigo}`,
 `ETAPA: ${r.etapa}`,
 `DOCUMENTO / EVIDÊNCIA: ${r.documento}`,
 `APLICABILIDADE: ${r.aplicabilidade}`,
 `CLASSIFICAÇÃO JURÍDICA: ${r.classificacao}`,
 `FUNDAMENTO: ${r.fundamento}`,
 `FONTE / URL: ${r.fonte_url}`,
 `SITUAÇÃO DA CONFERÊNCIA: ${keyStatusLabel(d.status)}.`,
 `PEDIDO: ${requestLanguage(r)}`,
 `OBSERVAÇÃO DO ANALISTA: ${d.notes||'Não informada.'}`)});
 lines.push('','3. PROVIDÊNCIAS E RESPOSTA',
 'Solicitamos, quando pertinente, a identificação do número do documento/processo SEI, data de emissão, contrato e competência do BM, bem como a indicação de páginas, cronogramas e demonstrativos utilizados. Caso a exigência não seja aplicável à situação concreta, solicitamos a respectiva justificativa, observando a classificação jurídica indicada na matriz. Não se presume descumprimento a partir da ausência de arquivo nesta sessão do BI.',
 '', 'Agradecemos os esclarecimentos, que subsidiarão a análise técnica e eventual atualização do acompanhamento pela SNP/MPOR.',
 '', 'Atenciosamente,','[Unidade responsável — preencher após revisão]','',
 'RASCUNHO NÃO ENVIADO — Revisão técnica/jurídica e aprovação da SNP necessárias antes de qualquer comunicação oficial.');
 const subject=`[RASCUNHO] PUC — Solicitação de esclarecimentos — ${p.empresa} — ${p.id} — ${[...chosenStages].sort().map(x=>x.slice(0,2)).join('/')}`;
 draftText=lines.join('\n');q('md-subject').value=subject;q('md-body').value=draftText;
 q('md-feedback').textContent=`Minuta gerada para revisão: ${selected.length} item(ns) documental(is), ${diffs.length} confronto(s) com divergência numérica. Nenhuma mensagem foi enviada.`;
 q('md-body').focus();
}
function blobDownload(filename,contents,type='text/plain;charset=utf-8'){
 const url=URL.createObjectURL(new Blob([contents],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);
}
async function copyDraft(){const msg=`Assunto: ${q('md-subject').value}\n\n${q('md-body').value}`;if(!q('md-body').value.trim()){q('md-feedback').textContent='Gere a minuta antes de copiar.';return}try{await navigator.clipboard.writeText(msg);q('md-feedback').textContent='Minuta copiada. Revise antes de enviar.'}catch{q('md-body').select();document.execCommand('copy');q('md-feedback').textContent='Texto selecionado; verifique a área de transferência.'}}
function emlDownload(){if(!q('md-body').value.trim()){q('md-feedback').textContent='Gere a minuta antes de exportar.';return}const subject=q('md-subject').value.replace(/[\r\n]+/g,' ').trim();const body=q('md-body').value.replace(/\r?\n/g,'\r\n');const payload=`X-Unsent: 1\r\nTo: \r\nSubject: ${subject}\r\nMIME-Version: 1.0\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: 8bit\r\n\r\n${body}`;blobDownload('PUC_minuta_'+currentId+'.eml',payload,'message/rfc822;charset=utf-8')}
