 q('md-checklist').addEventListener('change',e=>{const x=e.target;const code=x.dataset.mdInclude||x.dataset.mdStatus;if(!code)return;const d=decide(code);if(x.dataset.mdInclude)d.include=x.checked;else d.status=x.value;q('md-matrix-count').textContent=`${RULES.filter(r=>chosenStages.has(r.etapa)).length} requisitos da etapa · ${RULES.filter(r=>chosenStages.has(r.etapa)&&decide(r.codigo).include).length} selecionados`;});
 q('md-checklist').addEventListener('input',e=>{const code=e.target.dataset.mdNotes;if(code)decide(code).notes=e.target.value.slice(0,1500)});
